#!/usr/bin/env node
/**
 * gen-home-themes.mjs — bundle the downloadable theme families (`themes/<slug>/`, ADR 0036)
 * into the website (`apps/home`, ADR 0038) the way a consumer would copy them, so the site
 * never imports `../../themes` (RM-091).
 *
 * Writes `apps/home/themes/` — git-ignored (its own `.gitignore` is `*`), regenerated on every
 * `pnpm install` by the app's `postinstall` script, never hand-edited:
 *   - `<slug>/`     the family folder (stylesheets, `fonts/`, `theme.ts`; not README.md), each
 *                   stylesheet and `theme.ts` headed "GENERATED … do not edit"
 *   - `themes.css`  every family's `<slug>-fonts.css` first, then each `<slug>-{light,dark}.css`,
 *                   then the `@custom-variant dark` line (themes/README.md steps 2 and 4)
 *   - `index.ts`    `SITE_THEMES` (built-ins + every family's `<slug>Themes`, README step 3) and
 *                   `SITE_THEME_FAMILIES` (id, label, per-mode theme value + swatch colours
 *                   resolved from the stylesheets), in switcher order: default first
 *
 *   node scripts/gen-home-themes.mjs          # write
 *   node scripts/gen-home-themes.mjs --check  # exit 1 when apps/home/themes/ is stale or missing
 */
import {
  copyFileSync,
  existsSync,
  mkdirSync,
  readdirSync,
  readFileSync,
  rmSync,
  statSync,
  writeFileSync,
} from "node:fs";
import { dirname, join, relative } from "node:path";
import { fileURLToPath } from "node:url";

import { collectVariants, renderDarkVariant } from "./gen-community-themes.mjs";
import {
  COMMUNITY_THEMES_DIR,
  declarations,
  formatForPath,
  readRootDeclarations,
  resolveColor,
  themeBlocks,
} from "./lib/community-themes.mjs";

const REPO_ROOT = dirname(dirname(fileURLToPath(import.meta.url)));
export const HOME_THEMES_DIR = join(REPO_ROOT, "apps", "home", "themes");
const DEFAULT_THEMES_DIR = join(REPO_ROOT, "packages", "tokens", "src", "themes");
const SCRIPT = "scripts/gen-home-themes.mjs";

const header = (from) => `GENERATED by ${SCRIPT} from ${from} — do not edit.`;
const camel = (slug) => slug.replace(/[-_](\w)/g, (_, c) => c.toUpperCase());

/** `--background` / `--primary` of one theme block, resolved to oklch literals. */
function swatchOf(cssFile, name, root) {
  const block = themeBlocks(readFileSync(cssFile, "utf8")).find((b) => b.name === name);
  if (!block) throw new Error(`${relative(REPO_ROOT, cssFile)}: no [data-theme="${name}"] block`);
  const decls = declarations(block.body);
  const pick = (token) => {
    const value = resolveColor(token, decls, root);
    if (!value) throw new Error(`${name}: ${token} does not resolve to an oklch literal`);
    return value;
  };
  return { background: pick("--background"), primary: pick("--primary") };
}

/** Every family the site offers, default first — `{ id, label, themes, swatches }`. */
export function siteFamilies(variants = collectVariants()) {
  const root = readRootDeclarations();
  const families = [
    {
      id: "default",
      label: "Default",
      importName: null,
      themes: { light: "light", dark: "dark" },
      swatches: {
        light: swatchOf(join(DEFAULT_THEMES_DIR, "light.css"), "light", root),
        dark: swatchOf(join(DEFAULT_THEMES_DIR, "dark.css"), "dark", root),
      },
    },
  ];
  const bySlug = new Map();
  for (const v of variants) {
    const slug = relative(COMMUNITY_THEMES_DIR, dirname(v.file));
    if (!bySlug.has(slug)) bySlug.set(slug, []);
    bySlug.get(slug).push(v);
  }
  for (const [slug, vs] of bySlug) {
    const light = vs.find((v) => v.scheme === "light");
    const dark = vs.find((v) => v.scheme === "dark");
    if (!light || !dark)
      throw new Error(`themes/${slug}: the site needs both a light and a dark variant`);
    families.push({
      id: slug,
      label: vs.map((v) => v.definition?.familyLabel).find(Boolean) ?? slug,
      importName: `${camel(slug)}Themes`,
      themes: { light: light.name, dark: dark.name },
      swatches: {
        light: swatchOf(light.file, light.name, root),
        dark: swatchOf(dark.file, dark.name, root),
      },
    });
  }
  return { families, bySlug };
}

function renderIndex(families) {
  const custom = families.filter((f) => f.importName);
  const data = families.map(({ id, label, themes, swatches }) => ({ id, label, themes, swatches }));
  return `/* ${header("themes/")} */
import { BUILT_IN_THEME_DEFINITIONS, type ThemeDefinition } from "@elabs-ai/components-tokens";
${custom.map((f) => `import { ${f.importName} } from "./${f.id}/theme";`).join("\n")}

export interface SiteThemeSwatch {
  background: string;
  primary: string;
}

export interface SiteThemeFamily {
  /** Family id — the \`?theme=\` value (\`default\` for the built-in reference themes). */
  id: string;
  label: string;
  /** The \`data-theme\` value per mode. */
  themes: { light: string; dark: string };
  /** Resolved \`--background\` / \`--primary\` per mode (the switch's two-tone chip). */
  swatches: { light: SiteThemeSwatch; dark: SiteThemeSwatch };
}

/** Every theme the site registers on ThemeProvider (themes/README.md step 3). */
export const SITE_THEMES: readonly ThemeDefinition[] = [
  ...BUILT_IN_THEME_DEFINITIONS,
${custom.map((f) => `  ...${f.importName},`).join("\n")}
];

/** The families in switcher order, default first. */
export const SITE_THEME_FAMILIES: readonly SiteThemeFamily[] = ${JSON.stringify(data, null, 2)};
`;
}

function renderCss(variants) {
  const rel = (file) =>
    `@import "./${relative(COMMUNITY_THEMES_DIR, file).split("\\").join("/")}";`;
  const fonts = [...new Set(variants.map((v) => v.fonts).filter(Boolean))].map(rel);
  return [
    `/* ${header("themes/")} */`,
    ...fonts,
    ...variants.map((v) => rel(v.file)),
    renderDarkVariant(variants),
    "",
  ].join("\n");
}

/** Every output file → its content (string, or a source path for a byte copy). */
export async function expectedOutputs() {
  const variants = collectVariants();
  const { families, bySlug } = siteFamilies(variants);
  const out = new Map([[".gitignore", "# " + header("themes/") + "\n*\n"]]);
  const walk = (dir, slug) => {
    for (const name of readdirSync(dir).sort()) {
      const abs = join(dir, name);
      const rel = relative(COMMUNITY_THEMES_DIR, abs).split("\\").join("/");
      if (statSync(abs).isDirectory()) walk(abs, slug);
      else if (name === "README.md") continue;
      else if (/\.(css|ts)$/.test(name))
        out.set(rel, `/* ${header(`themes/${rel}`)} */\n${readFileSync(abs, "utf8")}`);
      else out.set(rel, { copy: abs });
    }
  };
  for (const slug of bySlug.keys()) walk(join(COMMUNITY_THEMES_DIR, slug), slug);
  out.set("themes.css", renderCss(variants));
  out.set("index.ts", renderIndex(families));
  for (const [rel, content] of out)
    if (typeof content === "string" && /\.(css|ts)$/.test(rel))
      out.set(rel, await formatForPath(join(HOME_THEMES_DIR, rel), content));
  return out;
}

function listFiles(dir, base = dir) {
  if (!existsSync(dir)) return [];
  return readdirSync(dir).flatMap((n) => {
    const abs = join(dir, n);
    return statSync(abs).isDirectory()
      ? listFiles(abs, base)
      : [relative(base, abs).split("\\").join("/")];
  });
}

const bytesOf = (content) =>
  typeof content === "string" ? Buffer.from(content) : readFileSync(content.copy);

async function main() {
  const check = process.argv.includes("--check");
  const expected = await expectedOutputs();
  if (check) {
    const onDisk = new Set(listFiles(HOME_THEMES_DIR));
    const stale = [...expected].filter(
      ([rel, c]) =>
        !onDisk.has(rel) || !readFileSync(join(HOME_THEMES_DIR, rel)).equals(bytesOf(c)),
    );
    const extra = [...onDisk].filter((rel) => !expected.has(rel));
    if (stale.length || extra.length) {
      console.error(
        `apps/home/themes/ is stale (${[...stale.map(([r]) => r), ...extra].join(", ")}) — run node ${SCRIPT}`,
      );
      process.exit(1);
    }
    console.log(`apps/home/themes/ is fresh (${expected.size} files)`);
    return;
  }
  rmSync(HOME_THEMES_DIR, { recursive: true, force: true });
  for (const [rel, content] of expected) {
    const abs = join(HOME_THEMES_DIR, rel);
    mkdirSync(dirname(abs), { recursive: true });
    if (typeof content === "string") writeFileSync(abs, content);
    else copyFileSync(content.copy, abs);
  }
  console.log(`apps/home/themes/: ${expected.size} files from themes/ (${SCRIPT})`);
}

if (process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]) await main();
